function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORE_TABLE = 1; // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ  
  const ORDER_TABLE = 7; // 発注データ
  const DEMAND_TABLE = 6; // 需要予測結果

  let currentOrders = [];
  let selectedOrderIds = new Set();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 店舗選択肢を読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORE_TABLE);
    if (!stores) return;

    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    stores.filter(store => store.有効フラグ).forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = `${store.店舗コード} - ${store.店舗名}`;
      storeSelect.appendChild(option);
    });
  }

  // 発注データ一覧を描画
  function renderOrderList(orders) {
    const tbody = container.querySelector('#order-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 40px;">
            発注対象のデータがありません
          </td>
        </tr>
      `;
      updateSummary();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const isSelected = selectedOrderIds.has(order.発注ID);
      const isSent = order.発注ステータス === '送信済み';

      let statusBadge = '';
      switch(order.発注ステータス) {
        case '送信待ち':
          statusBadge = '<span class="status-badge status-pending">送信待ち</span>';
          break;
        case '送信済み':
          statusBadge = '<span class="status-badge status-sent">送信済み</span>';
          break;
        case 'エラー':
          statusBadge = '<span class="status-badge status-error">送信エラー</span>';
          break;
        default:
          statusBadge = `<span class="status-badge">${order.発注ステータス || '未設定'}</span>`;
      }

      return `
        <tr data-id="${order.発注ID}" ${isSent ? 'style="opacity: 0.6;"' : ''}>
          <td>
            <input type="checkbox" 
                   class="order-checkbox" 
                   data-id="${order.発注ID}"
                   ${isSelected ? 'checked' : ''}
                   ${isSent ? 'disabled' : ''}>
          </td>
          <td>${order.商品コード || ''}</td>
          <td>${order.商品名 || ''}</td>
          <td style="text-align: right;">${order.予測数量 || 0}</td>
          <td style="text-align: right;">${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td class="amount-cell">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');

    updateSummary();
  }

  // 選択状況とサマリーを更新
  function updateSummary() {
    const selectedCount = selectedOrderIds.size;
    const totalAmount = currentOrders
      .filter(order => selectedOrderIds.has(order.発注ID))
      .reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    container.querySelector('#selected-count').textContent = `選択: ${selectedCount}件`;
    container.querySelector('#total-amount').textContent = `合計金額: ¥${totalAmount.toLocaleString()}`;

    const sendBtn = container.querySelector('#btn-send');
    sendBtn.disabled = selectedCount === 0;

    // 全選択チェックボックスの状態更新
    const selectAllCheckbox = container.querySelector('#select-all-checkbox');
    const availableOrders = currentOrders.filter(order => order.発注ステータス !== '送信済み');
    const availableIds = availableOrders.map(order => order.発注ID);
    const selectedAvailableCount = availableIds.filter(id => selectedOrderIds.has(id)).length;

    if (availableOrders.length === 0) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = false;
      selectAllCheckbox.disabled = true;
    } else if (selectedAvailableCount === 0) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = false;
      selectAllCheckbox.disabled = false;
    } else if (selectedAvailableCount === availableIds.length) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = true;
      selectAllCheckbox.disabled = false;
    } else {
      selectAllCheckbox.indeterminate = true;
      selectAllCheckbox.checked = false;
      selectAllCheckbox.disabled = false;
    }
  }

  // 店舗選択時の処理
  async function loadOrdersForStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      selectedOrderIds.clear();
      renderOrderList([]);
      return;
    }

    // 発注データを取得
    const orders = await window.aivicApi.list(ORDER_TABLE);
    if (!orders) {
      currentOrders = [];
      selectedOrderIds.clear();
      renderOrderList([]);
      return;
    }

    // 商品マスタを取得
    const products = await window.aivicApi.list(PRODUCT_TABLE);
    const productMap = {};
    if (products) {
      products.forEach(product => {
        productMap[product.商品ID] = product;
      });
    }

    // 需要予測結果を取得
    const demands = await window.aivicApi.list(DEMAND_TABLE);
    const demandMap = {};
    if (demands) {
      demands.forEach(demand => {
        const key = `${demand.店舗ID}_${demand.商品ID}`;
        demandMap[key] = demand;
      });
    }

    // 選択店舗の発注データをフィルタリングして拡張
    const storeOrders = orders
      .filter(order => order.店舗ID === storeId)
      .map(order => {
        const product = productMap[order.商品ID] || {};
        const demandKey = `${order.店舗ID}_${order.商品ID}`;
        const demand = demandMap[demandKey] || {};

        return {
          ...order,
          商品コード: product.商品コード,
          商品名: product.商品名,
          予測数量: demand.予測数量,
          仕入先名: product.仕入先名 || '未設定'
        };
      });

    currentOrders = storeOrders;
    selectedOrderIds.clear();
    renderOrderList(storeOrders);
  }

  // 発注送信処理
  async function sendSelectedOrders() {
    const selectedOrders = currentOrders.filter(order => selectedOrderIds.has(order.発注ID));

    if (selectedOrders.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    // 送信済みデータの重複チェック
    const alreadySent = selectedOrders.filter(order => order.発注ステータス === '送信済み');
    if (alreadySent.length > 0) {
      alert('選択したデータに送信済みの発注が含まれています。重複送信はできません。');
      return;
    }

    // 発注数量0の商品チェック
    const zeroQuantityOrders = selectedOrders.filter(order => !order.発注数量 || order.発注数量 === 0);
    if (zeroQuantityOrders.length > 0) {
      const proceed = confirm(`発注数量が0の商品が${zeroQuantityOrders.length}件含まれています。これらを除外して送信しますか？`);
      if (!proceed) return;

      // 発注数量0の商品を除外
      zeroQuantityOrders.forEach(order => selectedOrderIds.delete(order.発注ID));
      const validOrders = selectedOrders.filter(order => order.発注数量 > 0);

      if (validOrders.length === 0) {
        alert('送信可能な発注データがありません');
        return;
      }
    }

    // 確認ダイアログ表示
    const validOrderCount = selectedOrders.filter(order => order.発注数量 > 0).length;
    const totalAmount = selectedOrders
      .filter(order => order.発注数量 > 0)
      .reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    container.querySelector('#confirm-message').innerHTML = `
      ${validOrderCount}件の発注データを送信します。<br>
      合計金額: ¥${totalAmount.toLocaleString()}<br><br>
      送信しますか？
    `;
    container.querySelector('#confirm-dialog').style.display = 'flex';
  }

  // 実際の送信処理
  async function executeSend() {
    const selectedOrders = currentOrders.filter(order => 
      selectedOrderIds.has(order.発注ID) && order.発注数量 > 0
    );

    try {
      let successCount = 0;
      let errorCount = 0;

      for (const order of selectedOrders) {
        try {
          // 発注ステータスを送信済みに更新
          const updated = await window.aivicApi.update(ORDER_TABLE, order.発注ID, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString()
          });

          if (updated) {
            successCount++;
          } else {
            errorCount++;
          }
        } catch (error) {
          console.error('発注送信エラー:', error);
          errorCount++;
        }
      }

      // 結果通知
      if (errorCount === 0) {
        alert(`${successCount}件の発注データを正常に送信しました`);
      } else {
        alert(`送信完了: ${successCount}件\n送信失敗: ${errorCount}件`);
      }

      // 画面を再読み込み
      const storeId = container.querySelector('#store-select').value;
      if (storeId) {
        await loadOrdersForStore(storeId);
      }

    } catch (error) {
      console.error('送信処理エラー:', error);
      alert('送信処理中にエラーが発生しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', (e) => {
    loadOrdersForStore(e.target.value);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all-checkbox').addEventListener('change', (e) => {
    const availableOrders = currentOrders.filter(order => order.発注ステータス !== '送信済み');

    if (e.target.checked) {
      availableOrders.forEach(order => selectedOrderIds.add(order.発注ID));
    } else {
      availableOrders.forEach(order => selectedOrderIds.delete(order.発注ID));
    }

    renderOrderList(currentOrders);
  });

  // 個別チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;

      if (e.target.checked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }

      updateSummary();
    }
  });

  // 送信ボタン
  container.querySelector('#btn-send').addEventListener('click', sendSelectedOrders);

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778591852463'); // 発注管理画面
  });

  // 確認ダイアログ
  container.querySelector('#btn-confirm-ok').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').style.display = 'none';
    executeSend();
  });

  container.querySelector('#btn-confirm-cancel').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').style.display = 'none';
  });

  // 初期化
  loadStores();
}
